export function safetyCheck(safetyCheckFunction: () => Promise<boolean>, timeout: number): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    const timeoutId = setTimeout(() => {
      resolve(false);
    }, timeout);

    safetyCheckFunction()
      .then((result) => {
