        resolve(result);
      })
      .catch((error) => {
        clearTimeout(timeoutId);
        resolve(false);
      });
  });
}

import { Cache } from 'cache-manager';
import { Injectable } from '@nestjs/common';
import { ApprovalService } from './approval.service';

@Injectable()
class ApprovalCacheService {
  private cache: Cache;

  constructor(private approvalService: ApprovalService) {
    this.cache = Cache.getInstance();
  }

  async verifyApprovalToken(token: string): Promise<boolean> {
    const cachedResult = await this.cache.get(token);
    if (cachedResult !== undefined) {
      return cachedResult;
    }

    const isApproved = await this.approvalService.verifyApprovalToken(token);
    this.cache.set(token, isApproved);
    return isApproved;
  }
}

import { writeFile as fsWriteFile } from 'fs/promises';

export async function writeFile(filePath: string, data: string, options?: { maxFileSizeKB?: number }) {
  const maxFileSizeKB = options?.maxFileSizeKB ?? 1024; // Default to 1MB
  const maxSizeBytes = maxFileSizeKB * 1024;
  const dataBytes = Buffer.byteLength(data);

  if (dataBytes > maxSizeBytes) {
    throw new Error(`File size exceeds maximum allowed size of ${maxFileSizeKB}KB`);
  }

  await fsWriteFile(filePath, data);
}

import { escapeRegExp } from 'lodash';

export function sanitizeInput(input: string): string {
  const sanitizedInput = escapeRegExp(input);
  return sanitizedInput;
}

export function grep(pattern: string, text: string): string[] {
  const sanitizedPattern = sanitizeInput(pattern);
  const regex = new RegExp(sanitizedPattern, 'g');
  const matches = text.match(regex) || [];
  return matches;
}

