import { AgentState } from './types';

export class StateManager {
  private state: AgentState;
  private persistenceInterval: NodeJS.Timeout;

  constructor(state: AgentState) {
    this.state = state;
  }

  public async saveStateToDisk(): Promise<void> {
    try {
      const serializedState = JSON.stringify(this.state);
      const fs = require('fs');
      fs.writeFileSync('agent_state.json', serializedState);
      console.log('Agent state saved to disk successfully.');</n    } catch (error) {
      console.error('Failed to save agent state to disk:', error);
    }
  }

  public startPersistenceInterval(intervalMs: number): void {
    this.persistenceInterval = setInterval(() => {
      this.saveStateToDisk();
    }, intervalMs);
  }

  public stopPersistenceInterval(): void {
    clearInterval(this.persistenceInterval);
  }
}

